// Dot VPN type scale. Generated by design/scripts/generate.py; edit there.
// Needs the TTFs in res/font/ (see design/README.md, Android section).
package dot.vpn.payam.ui.theme

import androidx.compose.material3.Typography
import androidx.compose.ui.text.TextStyle
import androidx.compose.ui.text.font.Font
import androidx.compose.ui.text.font.FontFamily
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.em
import androidx.compose.ui.unit.sp
import dot.vpn.payam.R

val Geist = FontFamily(
    Font(R.font.geist_regular, FontWeight.W400),
    Font(R.font.geist_medium, FontWeight.W500),
    Font(R.font.geist_semibold, FontWeight.W600),
    Font(R.font.geist_bold, FontWeight.W700),
)
val GeistMono = FontFamily(
    Font(R.font.geist_mono_regular, FontWeight.W400),
    Font(R.font.geist_mono_medium, FontWeight.W500),
)
val Vazirmatn = FontFamily(
    Font(R.font.vazirmatn_regular, FontWeight.W400),
    Font(R.font.vazirmatn_medium, FontWeight.W500),
    Font(R.font.vazirmatn_bold, FontWeight.W700),
)

/** The scale from the design system, by token name. */
object DotType {
    val display = TextStyle(fontFamily = Geist, fontWeight = FontWeight.W600, fontSize = 48.sp, lineHeight = 52.sp, letterSpacing = (-0.04).em)
    val h1 = TextStyle(fontFamily = Geist, fontWeight = FontWeight.W600, fontSize = 32.sp, lineHeight = 40.sp, letterSpacing = (-0.03).em)
    val h2 = TextStyle(fontFamily = Geist, fontWeight = FontWeight.W600, fontSize = 24.sp, lineHeight = 32.sp, letterSpacing = (-0.02).em)
    val h3 = TextStyle(fontFamily = Geist, fontWeight = FontWeight.W600, fontSize = 18.sp, lineHeight = 26.sp, letterSpacing = (-0.01).em)
    val body = TextStyle(fontFamily = Geist, fontWeight = FontWeight.W400, fontSize = 16.sp, lineHeight = 24.sp, letterSpacing = (0).em)
    val small = TextStyle(fontFamily = Geist, fontWeight = FontWeight.W400, fontSize = 14.sp, lineHeight = 20.sp, letterSpacing = (0).em)
    val caption = TextStyle(fontFamily = Geist, fontWeight = FontWeight.W500, fontSize = 12.sp, lineHeight = 16.sp, letterSpacing = (0).em)
    val mono = TextStyle(fontFamily = GeistMono, fontWeight = FontWeight.W400, fontSize = 13.sp, lineHeight = 20.sp, letterSpacing = (0).em)
}

/** Persian: Vazirmatn, no negative tracking, 4sp more line height. Mono stays Latin. */
fun TextStyle.persian(): TextStyle =
    if (fontFamily == GeistMono) this
    else copy(fontFamily = Vazirmatn, letterSpacing = 0.em, lineHeight = (lineHeight.value + 4).sp)

fun dotTypography(persian: Boolean): Typography {
    fun TextStyle.l() = if (persian) persian() else this
    return Typography(
        displayMedium = DotType.display.l(),
        headlineLarge = DotType.h1.l(),
        headlineSmall = DotType.h2.l(),
        titleLarge = DotType.h3.l(),
        bodyLarge = DotType.body.l(),
        bodyMedium = DotType.small.l(),
        labelLarge = DotType.body.l().copy(fontWeight = FontWeight.W600),
        labelSmall = DotType.caption.l(),
    )
}
